            <p>请联系管理员为你的账号重置密码。</p>
            <p>如果你是管理员：在「权限 → 用户」中选择用户，点击「设置密码」即可重置。</p>
          </div>
        </Modal>
      </div>
      <Footer />
    </div>
  );
};

export default Login;

