        <Tooltip key="invoke" title="调用函数">
          <Button
            type="link"
            size="small"
            icon={<PlayCircleOutlined />}
            onClick={() => {
              const path = (record.menu?.path || '/game/functions') + `?fid=${encodeURIComponent(record.id)}`;
              history.push(path);
