          <Form.Item label='目标/连接串' name='target'>
            <Input placeholder='可选：如 postgres://user:pass@host:5432/db; redis://host:6379/0; clickhouse://host:9000/db' />
          </Form.Item>
        </Form>
      </Modal>
    </PageContainer>
  );
}

